 Future<void> _manualEntry()async{final id=widget.businessId;if(id==null)return;final r=await showDialog<_ManualResult>(context:context,builder:(_)=>const _ManualTransactionDialog());if(r==null||!mounted)return;try{await _repo.createManualTransaction(businessId:id,total:r.total,paymentMethod:r.paymentMethod,transactionAt:r.date,notes:r.notes);await _refresh();if(mounted)ScaffoldMessenger.of(context).showSnackBar(const SnackBar(content:Text('Transaksi manual berhasil disimpan.')));}catch(e){if(mounted)ScaffoldMessenger.of(context).showSnackBar(SnackBar(content:Text('Gagal menyimpan transaksi: $e')));}}
 @override Widget build(BuildContext context){final money=NumberFormat.currency(locale:'id_ID',symbol:'Rp ',decimalDigits:0);return RefreshIndicator(onRefresh:_refresh,child:FutureBuilder<List<TransactionSummary>>(future:_future,builder:(context,snapshot){final now=DateTime.now();final start=DateTime(now.year,now.month,now.day).subtract(Duration(days:_days-1));final transactions=(snapshot.data??const <TransactionSummary>[]).where((t)=>t.status=='completed'&&!t.transactionAt.toLocal().isBefore(start)).toList();final revenue=transactions.fold<double>(0,(v,t)=>v+t.total);final average=transactions.isEmpty?0.0:revenue/transactions.length;final payments=<String,double>{};for(final t in transactions){payments[t.paymentMethod]=(payments[t.paymentMethod]??0)+t.total;}final bestPayment=payments.entries.isEmpty?null:payments.entries.reduce((a,b)=>a.value>=b.value?a:b);return ListView(padding:const EdgeInsets.fromLTRB(16,12,16,28),children:[Row(crossAxisAlignment:CrossAxisAlignment.start,children:[const Expanded(child:IrkopSectionHeader(eyebrow:'Analitik bisnis',title:'Laporan Penjualan',subtitle:'Lihat performa penjualan dan pola pembayaran bisnis Anda.',icon:Icons.bar_chart_outlined,action:'Data aktual')),const SizedBox(width:8),FilledButton.icon(onPressed:widget.businessId==null?null:_manualEntry,icon:const Icon(Icons.add),label:const Text('Manual'))]),const SizedBox(height:14),SegmentedButton<int>(segments:const[ButtonSegment(value:7,label:Text('7 Hari')),ButtonSegment(value:30,label:Text('30 Hari')),ButtonSegment(value:90,label:Text('90 Hari'))],selected:{_days},onSelectionChanged:(v)=>setState(()=>_days=v.first)),const SizedBox(height:16),if(snapshot.connectionState!=ConnectionState.done)const LinearProgressIndicator(),const SizedBox(height:10),Row(children:[Expanded(child:_MetricCard(icon:Icons.payments_outlined,label:'Omzet',value:money.format(revenue))),const SizedBox(width:10),Expanded(child:_MetricCard(icon:Icons.receipt_long_outlined,label:'Transaksi',value:transac