}
class _MetricCard extends StatelessWidget{const _MetricCard({required this.icon,required this.label,required this.value});final IconData icon;final String label,value;@override Widget build(BuildContext context)=>Card(child:Padding(padding:const EdgeInsets.all(16),child:Row(children:[CircleAvatar(child:Icon(icon)),const SizedBox(width:12),Expanded(child:Column(crossAxisAlignment:CrossAxisAlignment.start,children:[Text(label,style:Theme.of(context).textTheme.labelLarge),const SizedBox(height:3),Text(value,style:Theme.of(context).textTheme.titleLarge?.copyWith(fontWeight:FontWeight.w800))]))])));}
class _ManualResult{const _ManualResult({required this.total,required this.paymentMethod,required this.date,required this.notes});final double total;final String paymentMethod,notes;final DateTime date;}
class _ManualTransactionDialog extends StatefulWidget{const _ManualTransactionDialog();@override State<_ManualTransactionDialog> createState()=>_ManualTransactionDialogState();}
class _ManualTransactionDialogState extends State<_ManualTransactionDialog>{final _key=GlobalKey<FormState>();final _total=TextEditingController();final _notes=TextEditingController();DateTime _date=DateTime.now();String _method='cash';@override void dispose(){_total.dispose();_notes.dispose();super.dispose();}Future<void> _pick()async{final max=DateTime.now();final p=await showDatePicker(context:context,initialDate:_date,firstDate:max.subtract(const Duration(days:30)),lastDate:max,helpText:'Tanggal transaksi manual');if(p!=null&&mounted)setState(()=>_date=p);}void _save(){if(!(_key.currentState?.validate()??false))return;final amount=double.tryParse(_total.text.replaceAll(RegExp(r'[^0-9]'),''))??0;if(amount<=0)return;Navigator.pop(context,_ManualResult(total:amount,paymentMethod:_method,date:DateTime(_date.year,_date.month,_date.day,12),notes:_notes.text));}@override Widget build(BuildContext context)=>AlertDialog(title:const Text('Tambah Transaksi Manual'),content:Form(key:_key,child:SingleChildScrollView(child:Column(mainAxisSize:MainAxisSize.min,children:[TextFormField(controller:_total,keyboardType:TextInputType.number,decoration:const InputDecoration(labelText:'Total transaksi',prefixText:'Rp '),validator:(v)=>v==null||v.trim().isEmpty?'Nominal wajib diisi.':null),const SizedBox(height:12),DropdownButtonFormField<String>(value:_method,decoration:const InputDecoration(labelText:'Metode pembayaran'),items:const[DropdownMenuItem(value:'cash',child:Text('Tunai')),DropdownMenuItem(value:'transfer',child:Text('Transfer'))],onChanged:(v){if(v!=null)setState(()=>_method=v);}),const SizedBox(height:12),ListTile(contentPadding:EdgeInsets.zero,leading:const Icon(Icons.calendar_month_outlined),title:const Text('Tanggal'),subtitle:Text('Pilih tanggal transaksi'),onTap:_pick),TextFormField(controller:_notes,maxLines:2,decoration:const InputDecoration(labelText:'Catatan (opsional)'))]))),actions:[TextButton(onPressed:()=>Navigator.pop(context),child:const Text('Batal')),FilledButton(onPressed:_save,child:const Text('Simpan'))]);}}
